class PocketFlexProcessor extends AudioWorkletProcessor{constructor(){super();this.engine=new PocketPerformanceDSP(sampleRate);this.zero=new Float32Array(128);this.port.onmessage=e=>{if(e.data.reset)this.engine=new PocketPerformanceDSP(sampleRate);else this.engine.set(e.data)};this.port.postMessage({ready:true})}process(inputs,outputs){const o=outputs[0],i=inputs[0];if(!o?.[0])return true;const empty=this.zero;try{const before=this.engine.type;this.engine.process(i?.[0]||empty,i?.[1]||i?.[0]||empty,o[0],o[1]||o[0]);if(before&&this.engine.type===0)this.port.postMessage({completed:true})}catch(e){o[0].set(i?.[0]||empty);if(o[1])o[1].set(i?.[1]||i?.[0]||empty);this.port.postMessage({error:e.message})}return true}}
registerProcessor('pocket-flex',PocketFlexProcessor);
class PocketRecallProcessor extends AudioWorkletProcessor{constructor(){super();this.capacity=Math.round(sampleRate*25);this.ring=[new Float32Array(this.capacity),new Float32Array(this.capacity)];this.write=0;this.available=0;this.port.onmessage=e=>{if(e.data.capture){const length=this.available,channels=this.ring.map(d=>{const o=new Float32Array(length);for(let i=0;i<length;i++)o[i]=d[(this.write-length+i+this.capacity)%this.capacity];return o});this.port.postMessage({channels,rate:sampleRate},channels.map(c=>c.buffer))}}}process(inputs,outputs){const input=inputs[0],output=outputs[0];for(const ch of output||[])ch.fill(0);if(input?.[0])for(let i=0;i<input[0].length;i++){this.ring[0][this.write]=input[0][i];this.ring[1][this.write]=(input[1]||input[0])[i];this.write=(this.write+1)%this.capacity;this.available=Math.min(this.capacity,this.available+1)}return true}}
registerProcessor('pocket-recall',PocketRecallProcessor);
